import React, { useState, useEffect } from "react";
import axios from "axios";
import { ArrowLeft, Save, Send, ChevronDown } from "lucide-react";

const GAMYAM_COLORS = {
  darkBg: '#0f0f10',
  darkCard: '#2c2c2d',
  darkGray: '#4a4a4b',
  orange: '#ff7c26',
  textLight: '#ffffff',
  textMuted: '#b2b2b3',
  textDim: '#8e8e8e',
  border: '#4a4a4b',
};

function RecruiterActionsPage({ application, onBack }) {
  const [selectedRound, setSelectedRound] = useState('Round 1');
  const [roundData, setRoundData] = useState({
    'Round 1': {
      panelNumber: '',
      interviewerName: '',
      interviewerEmail: '',
      interviewerPhone: '',
      scheduledDate: '',
      scheduledTime: '',
      interviewPlace: '',
      feedback: '',
      status: 'pending'
    },
    'Round 2': {
      panelNumber: '',
      interviewerName: '',
      interviewerEmail: '',
      interviewerPhone: '',
      scheduledDate: '',
      scheduledTime: '',
      interviewPlace: '',
      feedback: '',
      status: 'pending'
    },
    'Round 3': {
      panelNumber: '',
      interviewerName: '',
      interviewerEmail: '',
      interviewerPhone: '',
      scheduledDate: '',
      scheduledTime: '',
      interviewPlace: '',
      feedback: '',
      status: 'pending'
    },
    'Final Round': {
      panelNumber: '',
      interviewerName: '',
      interviewerEmail: '',
      interviewerPhone: '',
      scheduledDate: '',
      scheduledTime: '',
      interviewPlace: '',
      feedback: '',
      status: 'pending'
    }
  });

  const [currentRoundFromDB, setCurrentRoundFromDB] = useState('Round 1');
  const [saving, setSaving] = useState(false);
  const [sendingEmail, setSendingEmail] = useState(false);

  // Fetch all round data on mount
  useEffect(() => {
    const fetchRoundData = async () => {
      try {
        const response = await axios.get(
          `http://localhost:5000/api/recruiter-actions/${application._id}`
        );

        if (response.data) {
          setCurrentRoundFromDB(response.data.currentRound || 'Round 1');
          setSelectedRound(response.data.currentRound || 'Round 1');

          // Update all rounds data
          setRoundData({
            'Round 1': response.data.round1 || roundData['Round 1'],
            'Round 2': response.data.round2 || roundData['Round 2'],
            'Round 3': response.data.round3 || roundData['Round 3'],
            'Final Round': response.data.finalRound || roundData['Final Round']
          });
        }
      } catch (err) {
        console.error('Error fetching round data:', err);
      }
    };

    if (application._id) {
      fetchRoundData();
    }
  }, [application._id]);

  // Get current round's data
  const currentData = roundData[selectedRound];

  // Update field in current round
  const updateField = (field, value) => {
    setRoundData(prev => ({
      ...prev,
      [selectedRound]: {
        ...prev[selectedRound],
        [field]: value
      }
    }));
  };

  // Save current round data
  const handleSave = async () => {
    setSaving(true);
    try {
      await axios.post(
        `http://localhost:5000/api/recruiter-actions/${application._id}`,
        {
          currentRound: selectedRound,
          roundData: currentData
        }
      );
      alert('Interview details saved successfully!');
      setCurrentRoundFromDB(selectedRound);
    } catch (err) {
      console.error('Error saving:', err);
      alert('Failed to save interview details');
    }
    setSaving(false);
  };

  // Send interview invitation
  const handleSendInvitation = async () => {
    if (!currentData.scheduledDate || !currentData.scheduledTime || !currentData.interviewerName) {
      alert('Please fill in Date, Time, and Interviewer Name before sending invitation');
      return;
    }

    if (!window.confirm('Send interview invitation emails?')) return;

    setSendingEmail(true);
    try {
      // First save the data
      await axios.post(
        `http://localhost:5000/api/recruiter-actions/${application._id}`,
        {
          currentRound: selectedRound,
          roundData: currentData
        }
      );

      // Then send emails
      await axios.post('http://localhost:5000/api/send-interview-invitation', {
        applicantEmail: application.email,
        applicantName: application.name,
        interviewerEmail: currentData.interviewerEmail,
        interviewerName: currentData.interviewerName,
        jobTitle: application.jobTitle,
        scheduledDate: currentData.scheduledDate,
        scheduledTime: currentData.scheduledTime,
        interviewPlace: currentData.interviewPlace,
        roundStatus: selectedRound,
        panelNumber: currentData.panelNumber,
        interviewerPhone: currentData.interviewerPhone
      });

      alert('Interview invitations sent successfully!');
    } catch (err) {
      console.error('Error sending invitation:', err);
      alert('Failed to send invitations');
    }
    setSendingEmail(false);
  };

  // Promote to next round
  const handlePromoteToNextRound = async () => {
    const roundSequence = ['Round 1', 'Round 2', 'Round 3', 'Final Round'];
    const currentIndex = roundSequence.indexOf(selectedRound);

    if (currentIndex === roundSequence.length - 1) {
      alert('This is the final round. No further rounds available.');
      return;
    }

    const nextRound = roundSequence[currentIndex + 1];

    if (!window.confirm(`Promote ${application.name} to ${nextRound}?`)) return;

    try {
      await axios.post(
        `http://localhost:5000/api/applications/${application._id}/promote-round`,
        {
          nextRound: nextRound,
          message: `Congratulations! You have successfully cleared ${selectedRound} and have been selected for ${nextRound}.`
        }
      );

      alert(`Candidate promoted to ${nextRound}!`);

      // Switch to next round
      setSelectedRound(nextRound);
      setCurrentRoundFromDB(nextRound);
    } catch (err) {
      console.error('Error promoting candidate:', err);
      alert('Failed to promote candidate');
    }
  };

  const getRoundStyle = (round) => {
    const styles = {
      'Round 1': { background: "rgba(33, 150, 243, 0.2)", color: "#2196F3", border: "2px solid #2196F3" },
      'Round 2': { background: "rgba(156, 39, 176, 0.2)", color: "#ab47bc", border: "2px solid #ab47bc" },
      'Round 3': { background: "rgba(255, 152, 0, 0.2)", color: "#ff9800", border: "2px solid #ff9800" },
      'Final Round': { background: "rgba(76, 175, 80, 0.2)", color: "#4caf50", border: "2px solid #4caf50" }
    };
    return styles[round] || styles['Round 1'];
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <button onClick={onBack} style={styles.backBtn}>
          <ArrowLeft size={20} /> Back to Applications
        </button>
        <h1 style={styles.title}>Manage Interview - {application.name}</h1>
      </div>

      {/* Candidate Info Card */}
      <div style={styles.infoCard}>
        <h2 style={styles.cardTitle}>Candidate Information</h2>
        <div style={styles.infoGrid}>
          <div style={styles.infoItem}>
            <span style={styles.infoLabel}>Name:</span>
            <span style={styles.infoValue}>{application.name}</span>
          </div>
          <div style={styles.infoItem}>
            <span style={styles.infoLabel}>Email:</span>
            <span style={styles.infoValue}>{application.email}</span>
          </div>
          <div style={styles.infoItem}>
            <span style={styles.infoLabel}>Phone:</span>
            <span style={styles.infoValue}>{application.phone}</span>
          </div>
          <div style={styles.infoItem}>
            <span style={styles.infoLabel}>Position:</span>
            <span style={styles.infoValue}>{application.jobTitle}</span>
          </div>
          <div style={styles.infoItem}>
            <span style={styles.infoLabel}>Skills:</span>
            <span style={styles.infoValue}>{application.skillset}</span>
          </div>
          <div style={styles.infoItem}>
            <span style={styles.infoLabel}>Current Round:</span>
            <span style={{
              ...styles.roundBadge,
              ...getRoundStyle(currentRoundFromDB)
            }}>
              {currentRoundFromDB}
            </span>
          </div>
        </div>
      </div>

      {/* Round Selector */}
      <div style={styles.roundSelector}>
        <h2 style={styles.cardTitle}>
          <ChevronDown size={20} style={{ marginRight: '8px' }} />
          Select Interview Round
        </h2>
        <div style={styles.roundButtons}>
          {['Round 1', 'Round 2', 'Round 3', 'Final Round'].map((round) => (
            <button
              key={round}
              onClick={() => setSelectedRound(round)}
              style={{
                ...styles.roundButton,
                ...(selectedRound === round ? {
                  ...getRoundStyle(round),
                  fontWeight: '700',
                  transform: 'scale(1.05)'
                } : {
                  background: GAMYAM_COLORS.darkGray,
                  color: GAMYAM_COLORS.textMuted,
                  border: `1px solid ${GAMYAM_COLORS.border}`
                })
              }}
            >
              {round}
              {roundData[round].status === 'completed' && ' ✓'}
            </button>
          ))}
        </div>
        <p style={styles.roundNote}>
          Viewing: <strong style={{ color: GAMYAM_COLORS.orange }}>{selectedRound}</strong>
        </p>
      </div>

      {/* Interview Details Form */}
      <div style={styles.formCard}>
        <h2 style={styles.cardTitle}>{selectedRound} - Interview Details</h2>

        <div style={styles.formGrid}>
          <div style={styles.formGroup}>
            <label style={styles.label}>Panel Number</label>
            <input
              type="text"
              value={currentData.panelNumber}
              onChange={(e) => updateField('panelNumber', e.target.value)}
              style={styles.input}
              placeholder="e.g., 2025-10-2"
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Interviewer Name *</label>
            <input
              type="text"
              value={currentData.interviewerName}
              onChange={(e) => updateField('interviewerName', e.target.value)}
              style={styles.input}
              placeholder="e.g., John Doe"
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Interviewer Email</label>
            <input
              type="email"
              value={currentData.interviewerEmail}
              onChange={(e) => updateField('interviewerEmail', e.target.value)}
              style={styles.input}
              placeholder="interviewer@company.com"
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Interviewer Phone</label>
            <input
              type="tel"
              value={currentData.interviewerPhone}
              onChange={(e) => updateField('interviewerPhone', e.target.value)}
              style={styles.input}
              placeholder="e.g., 9876543210"
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Interview Date *</label>
            <input
              type="date"
              value={currentData.scheduledDate}
              onChange={(e) => updateField('scheduledDate', e.target.value)}
              style={styles.input}
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Interview Time *</label>
            <input
              type="time"
              value={currentData.scheduledTime}
              onChange={(e) => updateField('scheduledTime', e.target.value)}
              style={styles.input}
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Interview Location</label>
            <input
              type="text"
              value={currentData.interviewPlace}
              onChange={(e) => updateField('interviewPlace', e.target.value)}
              style={styles.input}
              placeholder="e.g., Office - Room 301 or Google Meet"
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Round Status</label>
            <select
              value={currentData.status}
              onChange={(e) => updateField('status', e.target.value)}
              style={styles.input}
            >
              <option value="pending">Pending</option>
              <option value="scheduled">Scheduled</option>
              <option value="completed">Completed</option>
              <option value="rejected">Rejected</option>
            </select>
          </div>

          <div style={{ ...styles.formGroup, gridColumn: '1 / -1' }}>
            <label style={styles.label}>Feedback / Notes</label>
            <textarea
              value={currentData.feedback}
              onChange={(e) => updateField('feedback', e.target.value)}
              style={{ ...styles.input, minHeight: '100px', resize: 'vertical' }}
              placeholder={`Enter feedback for ${selectedRound}...`}
            />
          </div>
        </div>

        {/* Action Buttons */}
        <div style={styles.actionButtons}>
          <button onClick={handleSave} style={styles.saveBtn} disabled={saving}>
            <Save size={18} />
            {saving ? 'Saving...' : 'Save Details'}
          </button>

          <button 
            onClick={handleSendInvitation} 
            style={styles.sendBtn}
            disabled={sendingEmail}
          >
            <Send size={18} />
            {sendingEmail ? 'Sending...' : 'Send Invitation'}
          </button>

          {selectedRound !== 'Final Round' && (
            <button 
              onClick={handlePromoteToNextRound} 
              style={styles.promoteBtn}
            >
              Promote to Next Round →
            </button>
          )}
        </div>
      </div>

      {/* All Rounds Summary */}
      <div style={styles.summaryCard}>
        <h2 style={styles.cardTitle}>Interview Progress Summary</h2>
        <div style={styles.summaryGrid}>
          {['Round 1', 'Round 2', 'Round 3', 'Final Round'].map((round) => (
            <div key={round} style={styles.summaryItem}>
              <div style={styles.summaryHeader}>
                <span style={{ ...styles.roundBadge, ...getRoundStyle(round) }}>
                  {round}
                </span>
                <span style={styles.statusBadge}>
                  {roundData[round].status || 'Pending'}
                </span>
              </div>
              <div style={styles.summaryDetails}>
                {roundData[round].interviewerName && (
                  <p style={styles.summaryText}>
                    👤 {roundData[round].interviewerName}
                  </p>
                )}
                {roundData[round].scheduledDate && (
                  <p style={styles.summaryText}>
                    📅 {new Date(roundData[round].scheduledDate).toLocaleDateString()} at {roundData[round].scheduledTime}
                  </p>
                )}
                {roundData[round].feedback && (
                  <p style={styles.summaryText}>
                    💬 {roundData[round].feedback.substring(0, 50)}
                    {roundData[round].feedback.length > 50 ? '...' : ''}
                  </p>
                )}
                {!roundData[round].interviewerName && !roundData[round].scheduledDate && (
                  <p style={{ ...styles.summaryText, color: GAMYAM_COLORS.textDim }}>
                    No data yet
                  </p>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

